#include <stddef.h>
#pragma pack(1)
struct S{char c;double n;};
int main(void){struct S s={2,40.0};return sizeof(s)==9&&_Alignof(struct S)==1&&offsetof(struct S,n)==1?(int)s.n+s.c:1;}

#include <stddef.h>
#pragma pack(2)
struct S{char c;double n;};
int main(void){struct S s={2,40.0};return sizeof(s)==10&&_Alignof(struct S)==2&&offsetof(struct S,n)==2?(int)s.n+s.c:1;}

