#pragma pack(4)
struct S{char c;double n;};
int main(void){struct S s={2,40.0};return sizeof(s)==12&&_Alignof(struct S)==4&&offsetof(struct S,n)==4?(int)s.n+s.c:1;}

#include <stddef.h>
#pragma pack(8)
struct S{char c;double n;};
