#include <stddef.h>
#pragma pack(push,outer,2)
struct A{char c;int n;};
#pragma pack(push,inner,1)
struct B{char c;int n;};
#pragma pack(pop,outer)
struct C{char c;int n;};
int main(void){return sizeof(struct A)==6&&offsetof(struct A,n)==2&&sizeof(struct B)==5&&sizeof(struct C)==8?42:1;}

#include <stddef.h>
#pragma pack(push,outer,2)
#pragma pack(push,inner,1)
#pragma pack(pop,outer,4)
struct S{char c;double n;};
int main(void){return offsetof(struct S,n)==4&&sizeof(struct S)==12?42:1;}

#include <stddef.h>
#pragma pack(2)
#pragma pack(push,known,1)
#pragma pack(pop,missing)
struct A{char c;int n;};
#pragma pack(pop)
struct B{char c;int n;};
int main(void){return sizeof(struct A)==5&&sizeof(struct B)==6?42:1;}

#include <stddef.h>
#pragma pack(1)
struct A{char c;int n;};
#pragma pack()
struct B{char c;int n;};
