#pragma pack(1)
#pragma pack(pop,2)
struct S{char c;int n;};
int main(void){return sizeof(struct S)==6?42:1;}

#include <stddef.h>
int main(void){
#pragma pack(push,1)
struct S{char c;int n;};struct S s={2,40};
#pragma pack(pop)
struct T{char c;int n;};return sizeof(s)==5&&sizeof(struct T)==8?s.c+s.n:1;}

#include <stddef.h>
#include "begin.h"
struct A{char c;int n;};
#include "end.h"
struct B{char c;int n;};
int main(void){return sizeof(struct A)==5&&sizeof(struct B)==8?42:1;}

#include <stddef.h>
#define PRAGMA(x) _Pragma(#x)
PRAGMA(pack(push,1))
struct S{char c;int n;};
PRAGMA(pack(pop))
int main(void){struct S s={20,22};return sizeof(s)==5?s.c+s.n:1;}

#include <stddef.h>
#define CAP 2
__pragma(pack(push,CAP))
struct S{char c;int n;};
__pragma(pack(pop))
int main(void){return sizeof(struct S)==6?42:1;}

#include <stddef.h>
#pragma pack(1)
#define RECORD struct
#define MAKE(T) T
MAKE(RECORD) S{char c;int n;};
int main(void){return sizeof(struct S)==5?42:1;}

#include <string.h>
#pragma pack(1)
#define S1(x) #x
#define S(x) S1(x)
#define T struct
const char *name=S(T);
int main(void){return strcmp(name,"struct")==0?42:1;}

#define H1(x) <x.h>
#define H(x) H1(x)
#pragma pack(1)
#include H(struct)
int main(void){return answer;}

#include <stddef.h>
struct S;
#pragma pack(1)
struct S{char c;int n;};
#pragma pack(8)
struct S *p;
int main(void){return sizeof(*p)==5?42:1;}

#include <stddef.h>
struct S{char c;int n;};
#pragma pack(1)
struct S object;
struct S *p=&object;
int main(void){return sizeof(object)==8&&offsetof(struct S,n)==4?42:1;}

#include <stddef.h>
#pragma pack(push,1)
typedef struct S{char c;int n;} S;
#pragma pack(pop)
S values[2]={{2,20},{3,22}};
int main(void){return sizeof(values)==10&&(char*)&values[1]-(char*)&values[0]==5?values[0].n+values[1].n:1;}

#include <stddef.h>
#pragma pack(1)
struct A{char c;int n;};
struct B{char c;struct A a;double d;};
int main(void){struct B b={1,{2,40},3};return sizeof(b)==14&&offsetof(struct B,a)==1&&offsetof(struct B,d)==6?b.a.c+b.a.n:1;}

#include <stddef.h>
#pragma pack(1)
struct S{char c;_Alignas(16) int n;};
int main(void){return _Alignof(struct S)==16&&offsetof(struct S,n)==16&&sizeof(struct S)==32?42:1;}

#include <stddef.h>
#pragma pack(1)
struct __declspec(align(16)) S{char c;int n;};
int main(void){return _Alignof(struct S)==16&&offsetof(struct S,n)==1&&sizeof(struct S)==16?42:1;}

#include <stddef.h>
struct __declspec(align(16)) A{int n;};
#pragma pack(1)
struct B{char c;struct A a;};
int main(void){return _Alignof(struct B)==16&&offsetof(struct B,a)==16&&sizeof(struct B)==32?42:1;}

#include <stddef.h>
#pragma pack(1)
struct S{char c;int n;unsigned char data[];};
int main(void){return sizeof(struct S)==5&&offsetof(struct S,data)==5?42:1;}

#include <stddef.h>
#pragma pack(1)
union U{char c;double d;};
int main(void){union U u={.d=42.0};return sizeof(u)==8&&_Alignof(union U)==1?(int)u.d:1;}

#include <stddef.h>
#pragma pack(1)
struct S{unsigned int a:3,b:5;int *p;};
int value=40;struct S s={2,3,&value};
int main(void){s.b=7;return sizeof(s)==12&&offsetof(struct S,p)==4&&s.b==7?s.a+*s.p:1;}

#include <stddef.h>
#pragma pack(1)
struct S{char c;unsigned int a:3,b:5;short n;};
int main(void){struct S s={1,2,3,40};s.b=7;return sizeof(s)==7&&offsetof(struct S,n)==5&&s.b==7?s.a+s.n:1;}

#include <stddef.h>
#pragma pack(2)
struct S{char c;unsigned int a:3;unsigned int :0;short n;};
int main(void){return sizeof(struct S)==8&&offsetof(struct S,n)==6?42:1;}

#include <stddef.h>
#pragma pack(1)
struct S{char c;int *p;};
int value=40;struct S s={2,&value};
int main(void){return sizeof(s)==9&&offsetof(struct S,p)==1?s.c+*s.p:1;}

#include <stddef.h>
#pragma pack(1)
struct S{char c;int *p;};
int a=20,b=22;struct S s[2]={{1,&a},{2,&b}};
int main(void){return sizeof(s)==18?*s[0].p+*s[1].p:1;}

#include <stddef.h>
#pragma pack(1)
struct S{char c;int (*f)(int);};
int plus(int n){return n+22;}struct S s={20,plus};
int main(void){return sizeof(s)==9?s.f(s.c):1;}

#include <stddef.h>
#pragma pack(1)
struct S{char c;int n;};volatile struct S s={2,20};
int main(void){s.n+=20;return s.c+s.n;}

#include <stddef.h>
#include "types.h"
extern struct S value;extern struct S pass(struct S);
int main(void){struct S s=pass(value);return sizeof(s)==9?s.c+*s.p:1;}

